package group.zn.zero.world;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;

class LocalWorldServiceTest {
 private LocalWorldService service(){LocalWorldService s=new LocalWorldService();s.createWorld(new World("w",0),List.of(new Shard("a","w",0),new Shard("b","w",0)));return s;}
 @Test void enterWorldAssignsInitialShard(){assertEquals("a",service().enterWorldAsync("e","w").toCompletableFuture().join().ownerShardId());}
 @Test void moveRequiresOwnerShard(){LocalWorldService s=service();s.enterWorldAsync("e","w").toCompletableFuture().join();assertThrows(Exception.class,()->s.moveEntityAsync("e","b",1,1).toCompletableFuture().join());}
 @Test void migrationLocksSourceBeforeHandoff(){LocalWorldService s=service();s.enterWorldAsync("e","w").toCompletableFuture().join();assertEquals(MigrationState.SOURCE_LOCKED,s.requestMigrationAsync("m","e","b").toCompletableFuture().join().state());assertEquals(EntityStatus.MIGRATING_OUT,s.entityStatus("e"));}
 @Test void targetRejectsStaleRouteEpoch(){LocalWorldService s=service();s.enterWorldAsync("e","w").toCompletableFuture().join();assertThrows(Exception.class,()->s.requestMigrationAsync("m","e","b",99).toCompletableFuture().join());}
 @Test void migrationIsIdempotentByMigrationId(){LocalWorldService s=service();s.enterWorldAsync("e","w").toCompletableFuture().join();assertSame(s.requestMigrationAsync("m","e","b").toCompletableFuture().join(),s.requestMigrationAsync("m","e","b").toCompletableFuture().join());}
 @Test void duplicateMigrationWithDifferentTargetRejected(){LocalWorldService s=service();s.enterWorldAsync("e","w").toCompletableFuture().join();s.requestMigrationAsync("m","e","b").toCompletableFuture().join();assertThrows(Exception.class,()->s.requestMigrationAsync("m","e","a").toCompletableFuture().join());}
 @Test void sourceRollbackKeepsEntityWhenPrepareFails(){LocalWorldService s=service();s.enterWorldAsync("e","w").toCompletableFuture().join();s.requestMigrationAsync("m","e","b").toCompletableFuture().join();s.prepareMigrationAsync("m",false).toCompletableFuture().join();assertEquals("a",s.snapshot("e").ownerShardId());assertEquals(EntityStatus.ACTIVE,s.entityStatus("e"));}
 @Test void rollbackPublishesSourceUnlockBeforeFinalFailure(){java.util.List<WorldEvent.Type> types=new java.util.ArrayList<>();LocalWorldService s=new LocalWorldService(new group.zn.zero.actor.scheduler.LocalActorScheduler(),e->types.add(e.type()),WorldMetrics.NOOP);s.createWorld(new World("w",0),List.of(new Shard("a","w",0),new Shard("b","w",0)));s.enterWorldAsync("e","w").toCompletableFuture().join();s.requestMigrationAsync("m","e","b").toCompletableFuture().join();assertEquals(MigrationState.FAILED,s.prepareMigrationAsync("m",false).toCompletableFuture().join().state());assertTrue(types.indexOf(WorldEvent.Type.MIGRATION_SOURCE_UNLOCKED)<types.indexOf(WorldEvent.Type.MIGRATION_ROLLED_BACK));}
 @Test void asyncMigrationCompletesWithoutStageJoins(){LocalWorldService s=service();s.enterWorldAsync("e","w").toCompletableFuture().join();assertEquals(MigrationState.COMPLETED,s.migrateAsync("m","e","b").toCompletableFuture().join().state());assertEquals("b",s.snapshot("e").ownerShardId());}
 @Test void targetCommitPublishesNewOwnerOnce(){AtomicInteger n=new AtomicInteger();LocalWorldService s=new LocalWorldService(new group.zn.zero.actor.scheduler.LocalActorScheduler(),e->{if(e.type()==WorldEvent.Type.MIGRATION_COMMITTED)n.incrementAndGet();},WorldMetrics.NOOP);s.createWorld(new World("w",0),List.of(new Shard("a","w",0),new Shard("b","w",0)));s.enterWorldAsync("e","w").toCompletableFuture().join();s.requestMigrationAsync("m","e","b").toCompletableFuture().join();s.prepareMigrationAsync("m").toCompletableFuture().join();s.commitMigrationAsync("m").toCompletableFuture().join();s.commitMigrationAsync("m").toCompletableFuture().join();assertEquals(1,n.get());}
 @Test void oldMoveRejectedAfterSourceLocked(){LocalWorldService s=service();s.enterWorldAsync("e","w").toCompletableFuture().join();s.requestMigrationAsync("m","e","b").toCompletableFuture().join();assertThrows(Exception.class,()->s.moveEntityAsync("e","a",1,1).toCompletableFuture().join());}
 @Test void queryReturnsRouteVersion(){LocalWorldService s=service();s.enterWorldAsync("e","w").toCompletableFuture().join();assertEquals(0,s.snapshot("e").routeEpoch());}
 @Test void eventHistoryRemainsBounded(){LocalWorldService s=service();s.enterWorldAsync("e","w").toCompletableFuture().join();for(int i=0;i<5000;i++){s.moveEntityAsync("e","a",i,i).toCompletableFuture().join();}assertEquals(4096,s.events().size());assertEquals(WorldEvent.Type.MOVED,s.events().getLast().type());}
 @Test void migrationMetricsAvoidHighCardinality(){AtomicInteger n=new AtomicInteger();WorldMetrics m=(op,result,reason)->{assertTrue(op.length()<30);assertTrue(result.length()<30);assertTrue(reason.length()<30);n.incrementAndGet();};LocalWorldService s=new LocalWorldService(new group.zn.zero.actor.scheduler.LocalActorScheduler(),e->{},m);s.createWorld("w","a");s.enterWorldAsync("e","w").toCompletableFuture().join();s.requestMigrationAsync("m","e","a").toCompletableFuture().join();assertTrue(n.get()>0);}
}
